An original C++17 implementation follows. It reads the official input format and writes one final height per line.

```cpp
#include <iostream>
#include <vector>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n,m;if(!(cin>>n>>m))return 0;
    vector<long long> h(n);for(auto &v:h)cin>>v;
    for(int j=0;j<m;++j){
        long long c,b=0;cin>>c;
        for(int i=0;i<n&&b<c;++i){
            long long reach=min(h[i],c),gain=max(0LL,reach-b);
            h[i]+=gain;b+=gain;
        }
    }
    for(auto v:h)cout<<v<<'\n';
}
