#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n;if(!(cin>>n))return 0;string s;cin>>s;
    vector<int> lengths;int t=n;
    for(int i=0;i<n;){
        if(s[i]=='0'){++i;continue;}
        int left=i;while(i<n&&s[i]=='1')++i;
        int len=i-left;lengths.push_back(len);
        if(left==0&&i==n){cout<<1<<'\n';return 0;}
        t=min(t,left==0||i==n?len-1:(len-1)/2);
    }
    int width=2*t+1,answer=0;
    for(int len:lengths)answer+=(len+width-1)/width;
    cout<<answer<<'\n';
}
