#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
using namespace std;
long long floor_div(long long x,long long positive){
    return x>=0?x/positive:-((-x+positive-1)/positive);
}
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int tests;if(!(cin>>tests))return 0;
    while(tests--){
        int n;cin>>n;vector<long long> h(n),a(n);vector<int> order(n);
        for(auto &v:h)cin>>v;for(auto &v:a)cin>>v;
        for(int i=0;i<n;++i){int rank;cin>>rank;order[rank]=i;}
        long long lo=0,hi=numeric_limits<long long>::max();bool possible=true;
        for(int r=0;r+1<n;++r){
            int i=order[r],j=order[r+1];
            long long slope=a[i]-a[j],need=h[j]-h[i]+1;
            if(slope>0)lo=max(lo,-floor_div(-need,slope));
            else if(slope<0)hi=min(hi,floor_div(-need,-slope));
            else if(need>0)possible=false;
        }
        cout<<(possible&&lo<=hi?lo:-1)<<'\n';
    }
}
